package app.exteraless.settings;
import android.app.Activity;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.Gravity;import android.widget.EditText;import android.widget.LinearLayout;import android.widget.TextView;import android.widget.Toast;
import org.telegram.messenger.AndroidUtilities;import org.telegram.messenger.R;import org.telegram.ui.ActionBar.ActionBar;import org.telegram.ui.ActionBar.AlertDialog;import org.telegram.ui.ActionBar.BaseFragment;import org.telegram.ui.ActionBar.Theme;import org.telegram.ui.Components.LayoutHelper;import app.exteraless.notifications.NotificationStudio;
public class RoflanNotificationStudioActivity extends BaseFragment{
 private TextView selected,body,caption;
 @Override public android.view.View createView(android.content.Context c){actionBar.setBackButtonImage(R.drawable.ic_ab_back);actionBar.setTitle("Notification Studio");actionBar.setItemsColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText),false);actionBar.setActionBarMenuOnItemClick(new ActionBar.ActionBarMenuOnItemClick(){@Override public void onItemClick(int id){if(id==-1)finishFragment();}});
 android.widget.ScrollView scroll=new android.widget.ScrollView(c);LinearLayout root=new LinearLayout(c);root.setOrientation(1);root.setPadding(AndroidUtilities.dp(18),AndroidUtilities.dp(18),AndroidUtilities.dp(18),AndroidUtilities.dp(24));root.setBackgroundColor(Theme.getColor(Theme.key_windowBackgroundGray));
 TextView h=label(c,"Предпросмотр уведомления",18,true);root.addView(h,LayoutHelper.createLinear(-1,-2,0,0,0,12));LinearLayout card=new LinearLayout(c);card.setOrientation(1);card.setPadding(AndroidUtilities.dp(16),AndroidUtilities.dp(14),AndroidUtilities.dp(16),AndroidUtilities.dp(14));GradientDrawable bg=new GradientDrawable();bg.setColor(Theme.getColor(Theme.key_windowBackgroundWhite));bg.setCornerRadius(AndroidUtilities.dp(16));card.setBackground(bg);
 TextView src=label(c,"TELEGRAM · СЕЙЧАС",11,false);src.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText));card.addView(src);TextView title=label(c,"Алексей",16,true);title.setPadding(0,AndroidUtilities.dp(8),0,AndroidUtilities.dp(4));card.addView(title);body=label(c,NotificationStudio.previewBody(NotificationStudio.getStyle()),14,false);card.addView(body);caption=label(c,NotificationStudio.getCaption(),12,false);caption.setTextColor(Color.WHITE);caption.setPadding(0,AndroidUtilities.dp(8),0,0);caption.setVisibility(NotificationStudio.getCaption().isEmpty()?android.view.View.GONE:android.view.View.VISIBLE);card.addView(caption);root.addView(card,LayoutHelper.createLinear(-1,-2,0,0,0,14));
 selected=action(c,"Стиль · "+NotificationStudio.STYLE_NAMES[NotificationStudio.getStyle()]);selected.setOnClickListener(v->choose());root.addView(selected,LayoutHelper.createLinear(-1,48,0,0,0,8));TextView cap=action(c,"Изменить подпись уведомлений");cap.setOnClickListener(v->editCaption());root.addView(cap,LayoutHelper.createLinear(-1,48,0,0,0,8));TextView custom=action(c,"Конструктор моего стиля");custom.setOnClickListener(v->editCustomLayout());root.addView(custom,LayoutHelper.createLinear(-1,48,0,0,0,8));TextView accent=action(c,"Настроить цвет акцента");accent.setOnClickListener(v->editAccent());root.addView(accent,LayoutHelper.createLinear(-1,48,0,0,0,8));
 TextView note=label(c,"Цвет текста в системной шторке Android выбирается ОС. В предпросмотре подпись показана белым; акцент уведомления настраивается отдельно.",12,false);note.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText));note.setPadding(AndroidUtilities.dp(2),AndroidUtilities.dp(10),AndroidUtilities.dp(2),0);root.addView(note);scroll.setFillViewport(true);scroll.addView(root);android.widget.FrameLayout frame=new android.widget.FrameLayout(c);frame.addView(scroll,LayoutHelper.createFrame(-1,-1));frame.addView(actionBar,LayoutHelper.createFrame(-1,-2,Gravity.TOP));fragmentView=frame;return frame;}
 private TextView label(android.content.Context c,String s,int size,boolean bold){TextView v=new TextView(c);v.setText(s);v.setTextSize(size);v.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText));if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}
 private TextView action(android.content.Context c,String s){TextView v=label(c,s,14,false);v.setGravity(Gravity.CENTER_VERTICAL);v.setPadding(AndroidUtilities.dp(14),0,AndroidUtilities.dp(14),0);v.setBackground(Theme.createRoundRectDrawable(AndroidUtilities.dp(12),Theme.getColor(Theme.key_windowBackgroundWhite)));return v;}
 private void choose(){Activity a=getParentActivity();if(a==null)return;new AlertDialog.Builder(a).setTitle("Выбери стиль").setItems(NotificationStudio.STYLE_NAMES,(d,w)->{NotificationStudio.setStyle(w);refresh();}).setNegativeButton("Отмена",null).show();}
 private void refresh(){if(selected!=null)selected.setText("Стиль · "+NotificationStudio.STYLE_NAMES[NotificationStudio.getStyle()]);if(body!=null)body.setText(NotificationStudio.previewBody(NotificationStudio.getStyle()));if(caption!=null){String value=NotificationStudio.getCaption();caption.setText(value);caption.setVisibility(value.isEmpty()?android.view.View.GONE:android.view.View.VISIBLE);}}
 private void editCaption(){Activity a=getParentActivity();if(a==null)return;EditText e=new EditText(a);e.setSingleLine(true);e.setText(NotificationStudio.getCaption());e.setHint(NotificationStudio.DEFAULT_CAPTION);new AlertDialog.Builder(a).setTitle("Подпись уведомлений").setView(e).setPositiveButton("Сохранить",(d,w)->{NotificationStudio.setCaption(e.getText().toString());refresh();}).setNeutralButton("Сбросить",(d,w)->{NotificationStudio.setCaption(NotificationStudio.DEFAULT_CAPTION);refresh();}).setNegativeButton("Отмена",null).show();}
 private void editCustomLayout(){Activity a=getParentActivity();if(a==null)return;String[] layouts={"Оригинальный Telegram","Крупный текст","Список сообщений","Диалог"};new AlertDialog.Builder(a).setTitle("Основа моего стиля").setItems(layouts,(d,w)->{NotificationStudio.setCustomLayout(w);NotificationStudio.setStyle(8);refresh();}).setNegativeButton("Отмена",null).show();}
 private void editAccent(){Activity a=getParentActivity();if(a==null)return;EditText e=new EditText(a);e.setSingleLine(true);e.setText(String.format(java.util.Locale.US,"#%06X",0xFFFFFF&NotificationStudio.getCustomAccentColor()));new AlertDialog.Builder(a).setTitle("Цвет акцента · HEX").setView(e).setPositiveButton("Сохранить",(d,w)->{try{NotificationStudio.setCustomAccentColor(Color.parseColor(e.getText().toString().trim()));Toast.makeText(a,"Цвет сохранён",Toast.LENGTH_SHORT).show();}catch(Exception ex){Toast.makeText(a,"Неверный HEX-цвет",Toast.LENGTH_SHORT).show();}}).setNegativeButton("Отмена",null).show();}
}